function singleLanguage(s,lang) {
  const parts=s.split(/\s+[\/·]\s+/);
  if(parts.length>1 && parts.some(p=>/[\u0600-\u06ff]/.test(p)) && parts.some(p=>/[A-Za-z]/.test(p))) {
    const matching=parts.filter(p=>lang==='ar'?/[\u0600-\u06ff]/.test(p):/[A-Za-z]/.test(p));
    if(matching.length) return matching.join(' / ');
  }
  return s;
}
